import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {pathToFileURL} from 'node:url';
import {resolve} from 'node:path';
import {writeFile} from 'node:fs/promises';
const mode=process.argv[2];assert(['es','cjs'].includes(mode));const require=createRequire(import.meta.url),load=name=>mode==='es'?import(pathToFileURL(resolve(`artifacts/yjs-admission-build-20261107/${name}.js`)).href):require(`./yjs-admission-build-20261107/${name}.cjs`);
const [Y,engine,adapter,checkpoints]=await Promise.all([mode==='es'?import('yjs'):require('yjs'),load('engine'),load('adapter'),load('checkpoint')]);
assert.equal(typeof globalThis.document,'undefined');assert.equal(typeof globalThis.window,'undefined');
const {CoreExtension,composeExtensions,createEditor,getCollaborationState,reconnectCollaboration,disconnectCollaboration}=engine,{createRetainedYjsCollaborationExtension}=adapter,version='admission-node-1',cases=[],cleanup=[];
const document=()=>{const doc=new Y.Doc();cleanup.push(()=>doc.destroy());return doc;},content=text=>({type:'doc',content:[{type:'paragraph',content:[{type:'text',text}]}]});
function make(doc,text,extra={}){const kit=composeExtensions([CoreExtension,createRetainedYjsCollaborationExtension({document:doc,user:{id:'author',name:'Author',color:'#7048e8'},...extra})]),editor=createEditor({schema:kit.schema,plugins:kit.plugins,content:content(text)});cleanup.push(()=>editor.destroy());return editor;}
function deferred(){let resolve,reject;const promise=new Promise((yes,no)=>{resolve=yes;reject=no});return {resolve,reject,promise};}
async function settled(editor,status='connected'){for(let attempt=0;attempt<2000;attempt++){if(getCollaborationState(editor).status===status)return;await new Promise(done=>setTimeout(done,1));}assert.equal(getCollaborationState(editor).status,status);}
const serverDoc=document(),server=make(serverDoc,'Authoritative'),checkpoint=await checkpoints.captureRetainedCheckpoint(serverDoc,server.state.schema,version),admission=load=>({admission:{schemaVersion:version,load}});
try{
 const client=document(),pending=deferred();let starts=0;const joined=make(client,'Template',{provider:{connect(){starts++;assert.equal(client.getXmlFragment('fountain').length,1);}},...admission(()=>pending.promise)});
 assert.equal(getCollaborationState(joined).status,'connecting');assert.equal(client.getXmlFragment('fountain').length,0);assert.equal(starts,0);pending.resolve(checkpoint);await settled(joined);assert.deepEqual(joined.getJSON(),server.getJSON());assert.equal(starts,1);cases.push('validated authoritative checkpoint precedes provider start without client seed');
 const secondDoc=document(),second=make(secondDoc,'Other template',admission(()=>checkpoint));await settled(second);joined.dispatch(joined.createTransaction().insertText([0,0],0,'LEFT '));second.dispatch(second.createTransaction().insertText([0,0],second.state.doc.child(0).textContent.length,' RIGHT'));const a=Y.encodeStateAsUpdate(client),b=Y.encodeStateAsUpdate(secondDoc);Y.applyUpdate(client,b);Y.applyUpdate(secondDoc,a);assert.deepEqual(joined.getJSON(),second.getJSON());assert.equal(joined.getText(),'LEFT Authoritative RIGHT');assert.equal(client.getXmlFragment('fountain').length,1);cases.push('two independently empty clients share one native root and converge author edits');
 const draftDoc=document(),draftWait=deferred(),draft=make(draftDoc,'Template',admission(()=>draftWait.promise)),empty=Y.encodeStateAsUpdate(draftDoc);draft.dispatch(draft.createTransaction().insertText([0,0],0,'DRAFT '));draftWait.resolve(checkpoint);await settled(draft,'error');assert.equal(draft.getText(),'DRAFT Template');assert.deepEqual(Y.encodeStateAsUpdate(draftDoc),empty);reconnectCollaboration(draft);await settled(draft,'error');assert.equal(draft.getText(),'DRAFT Template');cases.push('pending local draft remains visible and cannot be overwritten on implicit retry');
 const cancelDoc=document(),cancelWait=deferred();let signal;const cancelled=make(cancelDoc,'Template',admission(value=>{signal=value;return cancelWait.promise}));disconnectCollaboration(cancelled);assert(signal.aborted);cancelWait.resolve(checkpoint);await new Promise(done=>setTimeout(done,20));assert.equal(getCollaborationState(cancelled).status,'disconnected');assert.equal(cancelDoc.getXmlFragment('fountain').length,0);cases.push('cancelled admission cannot seed or revive a disconnected client');
 const conflictDoc=document(),conflicting=make(conflictDoc,'Independent draft');conflicting.destroy();const bytes=Y.encodeStateAsUpdate(conflictDoc),conflict=make(conflictDoc,'Independent draft',admission(()=>checkpoint));await settled(conflict,'error');assert.deepEqual(Y.encodeStateAsUpdate(conflictDoc),bytes);assert.equal(conflict.getText(),'Independent draft');cases.push('independent room conflicts preserve both source documents');
 const badDoc=document(),broken=checkpoint.update;broken[broken.length-1]^=1;const bad=make(badDoc,'Template',admission(()=>({manifest:checkpoint.manifest,update:broken})));await settled(bad,'error');assert.equal(badDoc.getXmlFragment('fountain').length,0);assert.equal(bad.getText(),'Template');cases.push('checksum failure does not import authoritative bytes or replace the draft');
 const result={mode,passed:cases.length,cases,node:process.version,dom:false};await writeFile(`artifacts/yjs-admission-node-${mode}-20261107.json`,JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result));
}finally{while(cleanup.length)cleanup.pop()();}
